def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Store internal attributes
    attrs = {
        "__srid_map__": srid_map,
        "__field_names__": tuple(fields),
    }

    # Create a writable attribute for each field name
    for field in fields:
        # property getter and setter that use a private attribute
        attrs[field] = property(
            lambda self, f=field: getattr(self, f"_{f}", None),
            lambda self, value, f=field: setattr(self, f"_{f}", value),
        )

    Base = Point

    def __init__(self, *coords, srid=None, **kwargs):
        # Initialize the base Point with provided coordinates
        Base.__init__(self, *coords)
        # Set the SRID, defaulting to the mapping's default entry if provided
        self.srid = srid if srid is not None else srid_map.get("default")
        # Set any keyword arguments that correspond to defined fields
        for key, value in kwargs.items():
            if key in attrs:
                setattr(self, key, value)

    attrs["__init__"] = __init__

    # Create and return the new subclass
    return type(name, (Point,), attrs)

