def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    # Default R options to apply before executing any R code
    r_options = {
        "scipen": 999,            # avoid scientific notation
        "digits": 15,             # use a higher number of digits for printing
        "warn": 2,                # turn warnings into errors
        "max.print": 10000,       # increase the number of printed items
        "character.only": True,   # ensure character strings are treated properly
    }

    def _r_repr(value):
        if isinstance(value, bool):
            return "TRUE" if value else "FALSE"
        if isinstance(value, str):
            return f'"{value}"'
        return str(value)

    opt_lines = [f"options({name}={_r_repr(val)})" for name, val in r_options.items()]
    return "\n".join(opt_lines) + "\n" + code

