def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    if maxsize < 0:
        raise ValueError('maxsize must be non-negative')
    def decorator(func):
        cache = collections.OrderedDict()
        def make_key(*args, **kwargs):
            if kwargs:
                kw_items = tuple(sorted(kwargs.items()))
            else:
                kw_items = ()
            if typed:
                # include types in key to differentiate values of same value but different types
                type_args = tuple(type(v) for v in args)
                type_kws = tuple(type(v) for k, v in kw_items)
                key = (*args, kw_items, type_args, type_kws)
            else:
                key = (*args, kw_items)
            return key
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = make_key(*args, **kwargs)
            now = timer()
            if key in cache:
                result, stamp = cache[key]
                if now - stamp <= ttl:
                    cache.move_to_end(key)
                    return result
                # expired
                del cache[key]
            result = func(*args, **kwargs)
            if maxsize and len(cache) >= maxsize:
                cache.popitem(last=False)
            cache[key] = (result, now)
            return result
        return wrapper
    return decorator

