def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    coord = np.asarray(coord)
    # Ensure coord is 2-D: (N_points, ndim)
    if coord.ndim == 1:
        points = coord.reshape(1, -1)
    else:
        points = coord
    n_points = points.shape[0]
    ndim = len(self.edges)
    if points.shape[1] != ndim:
        raise ValueError(f"coord dimension {points.shape[1]} does not match histogram {ndim}")
    # Determine bin indices for each point in each dimension
    inds = np.empty((n_points, ndim), dtype=int)
    for i in range(ndim):
        edges_i = self.edges[i]
        inds[:, i] = np.searchsorted(edges_i, points[:, i], side='right') - 1
    # Build mask of points that fall inside all bins
    mask = np.ones(n_points, dtype=bool)
    for i in range(ndim):
        mask &= (inds[:, i] >= 0) & (inds[:, i] < len(self.edges[i]) - 1)
    # Filter indices and weights for valid points
    valid_inds = inds[mask]
    if np.isscalar(weight):
        w = np.full(valid_inds.shape[0], weight)
    else:
        w = np.asarray(weight)
        if w.ndim == 0:
            w = np.full(valid_inds.shape[0], w)
        else:
            if w.shape[0] != n_points:
                raise ValueError("weight array length must match number of points")
            w = w[mask]
    # Increment histogram bins
    for idx, wt in zip(valid_inds, w):
        self.data[tuple(idx)] += wt
    return

