def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_map = {}

    # Case 1: inventory is a dict mapping version to a mapping of logical_path -> files
    if isinstance(inventory, dict):
        if version in inventory:
            mapping = inventory[version]
            if isinstance(mapping, dict):
                for lp, files in mapping.items():
                    if isinstance(files, (list, set, tuple)):
                        logical_map.setdefault(lp, set()).update(files)
                    else:
                        logical_map.setdefault(lp, set()).add(files)
            else:
                # Assume iterable of (logical_path, files) tuples
                for lp, files in mapping:
                    if isinstance(files, (list, set, tuple)):
                        logical_map.setdefault(lp, set()).update(files)
                    else:
                        logical_map.setdefault(lp, set()).add(files)

    # Case 2: inventory is an iterable of entry dicts with 'version', 'logical_path', 'content_file'
    else:
        for entry in inventory:
            if entry.get("version") == version:
                lp = entry.get("logical_path")
                if lp is None:
                    continue
                files = entry.get("content_file")
                if isinstance(files, (list, set, tuple)):
                    logical_map.setdefault(lp, set()).update(files)
                else:
                    logical_map.setdefault(lp, set()).add(files)

    return logical_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}

    for logical_path, entries in inventory.items():
        # entries can be a dict mapping version -> list/set of files
        if isinstance(entries, dict):
            files_set = set()
            for ver, files in entries.items():
                try:
                    # include files for the requested version or any later version
                    if ver == version or ver > version:
                        if isinstance(files, (list, set, tuple)):
                            files_set.update(files)
                except Exception:
                    # fallback for non-orderable types
                    if ver == version:
                        if isinstance(files, (list, set, tuple)):
                            files_set.update(files)
            if files_set:
                result[logical_path] = files_set
        # entries can be a list of dicts with a 'version' key
        elif isinstance(entries, list):
            files_set = set()
            for entry in entries:
                if isinstance(entry, dict) and entry.get('version') == version:
                    files = entry.get('files', [])
                    if isinstance(files, (list, set, tuple)):
                        files_set.update(files)
            if files_set:
                result[logical_path] = files_set
        # entries could be a simple list/set/tuple of files
        elif isinstance(entries, (list, set, tuple)):
            result[logical_path] = set(entries)

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if version not in inventory:
        raise ValueError(f"Version {version!r} not found in inventory")
    result = {}
    current_state = inventory[version].get("state", {})
    for logical_path, files in current_state.items():
        if isinstance(files, (list, set, tuple)):
            result[logical_path] = set(files)
        else:
            result[logical_path] = {files}
    # add duplicate references from later versions
    for v in inventory:
        if v == version:
            continue
        # sort and compare lexicographically; fall back to string compare
        try:
            if v > version:
                later_state = inventory[v].get("state", {})
                for logical_path, files in later_state.items():
                    if logical_path in result:
                        if isinstance(files, (list, set, tuple)):
                            result[logical_path].update(files)
                        else:
