    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Ensure the inventory contains mapping for each version to a dict of
    # logical_path -> iterable of content files
    base_map = inventory.get(version, {})
    logical_path_map = {lp: set(files) for lp, files in base_map.items()}

    # Include possible duplicate references from later versions
    for v, data in inventory.items():
        # Skip the current and earlier versions
        if v <= version:
            continue
        for lp, files in data.items():
            if lp in logical_path_map:
                logical_path_map[lp].update(files)

    return logical_path_map

