                        if hasattr(child, "digest") and hasattr(child, "compute_digest"):
                            expected = getattr(child, "digest")
                            actual = child.compute_digest()
                            if expected != actual:
                                is_valid = False
                                if show_warnings:
                                    print(f"[WARNING] Digest mismatch for {child} (expected {expected}, got {actual})")
                    except Exception as exc:
                        # Skip digest check if it fails, but keep validation status
                        if show_warnings:
                            print(f"[WARNING] Digest check could not be performed for {child}: {exc}")

                if is_valid:
                    good_objects += 1

                # Recurse into child nodes
                _traverse(child)

    # Start traversal from the root of the hierarchy
    _traverse(self._root)

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Iterate over all objects in the hierarchy.  The concrete iterator
    # (`_iter_hierarchy`) is expected to be provided by the subclass.
    for obj in self._iter_hierarchy():
        num_objects += 1
        is_valid = True

        if validate_objects:
            try:
                self._validate_obj(obj)
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Validation failed for object {obj!r}: {exc}")

        if check_digests:
            try:
                if not self._check_digest(obj):
                    is_valid = False
                    if show_warnings:
                        print(f"Digest mismatch for object {obj!r}")
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Digest check error for object {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

