def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise ValueError("version must be a string")

    # Helper to increment a numeric string preserving leading zeros
    def inc(num_str):
        stripped = num_str.lstrip('0')
        if stripped == '':
            # all zeros
            stripped = '0'
        inc_num = str(int(stripped) + 1)
        # preserve original width unless overflowed
        if len(inc_num) < len(num_str):
            return inc_num.zfill(len(num_str))
        return inc_num

    # If the entire string is numeric
    if version.isdigit():
        return inc(version)

    # Search for trailing number to increment
    import re
    m = re.search(r'(\d+)$', version)
    if m:
        start, end = m.span(1)
        return version[:start] + inc(m.group(1))

    # No numeric part, just append '1'
    return f"{version}1"

