def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    if not os.path.exists(path):
        return f"Error: path does not exist: {path}"

    if os.path.isfile(path):
        return 'file'

    if os.path.isdir(path):
        try:
            # Check for Namaste files directly in this directory
            namaste_files = [
                f for f in os.listdir(path)
                if os.path.isfile(os.path.join(path, f)) and f.startswith('0=')
            ]
            if namaste_files:
                return 'object'

            # If no Namaste file, assume storage root if it contains subdirectories
            subdirs = [
                d for d in os.listdir(path)
                if os.path.isdir(os.path.join(path, d))
            ]
            if subdirs:
                return 'root'

            # Empty directory – unclear what it is
            return f"Error: empty directory at {path}"
        except OSError as e:
            return f"Error accessing directory: {e}"

    return f"Error: unknown path type for {path}"

