def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode key, Node value) tuples. Duplicate keys
    (identified by ScalarNode.value) are merged: if both values are mapping
    nodes, their contents are recursively merged; otherwise the later value
    wins. The function returns a new list with merged content.
    """
    # Helper to determine if a node is a MappingNode
    def _is_mapping(node):
        return hasattr(node, "value") and isinstance(node.value, list)

    # Recursively merge two mapping nodes
    def _merge_mapping_nodes(m1, m2):
        """
        Merge mapping node m2 into m1 in place and return m1.
        """
        mapping = {}
        # Populate with entries from m1
        for k, v in m1.value:
            mapping[k.value] = [k, v]
        # Merge entries from m2
        for k, v in m2.value:
            key = k.value
            if key in mapping:
                existing_val = mapping[key][1]
                if _is_mapping(existing_val) and _is_mapping(v):
                    _merge_mapping_nodes(existing_val, v)
                else:
                    mapping[key][1] = v
            else:
                mapping[key] = [k, v]
        # Reconstruct the ordered value list
        m1.value = [pair[1] for pair in mapping.values()]
        return m1

    result = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in result:
            result[key] = (key_node, value_node)
        else:
            _, existing_value = result[key]
            if _is_mapping(existing_value) and _is_mapping(value_node):
                merged = _merge_mapping_nodes(existing_value, value_node)
                result[key] = (key_node, merged)
            else:
                # last value wins
                result[key] = (key_node, value_node)

    # Preserve the order of first insertion
    return list(result.values())

def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, Node) tuples for borgmatic YAML configs.
    Duplicate keys are merged recursively. When the value for a duplicate key
    is a plain scalar or any non‑MappingNode, the later one wins.
    """
    def _merge_mapping_nodes(a, b):
        # a and b are MappingNode instances
        merged = {}
        for key_a, val_a in a.value:
            merged[key_a.value] = (key_a, val_a)
        for key_b, val_b in b.value:
            if key_b.value in merged:
                key_a, val_a = merged[key_b.value]
                merged[key_b.value] = (key_a, _merge_values(val_a, val_b))
            else:
                merged[key_b.value] = (key_b, val_b)
        return ruamel.yaml.nodes.MappingNode(a.tag, list(merged.values()))

    def _merge_values(a, b):
        if isinstance(a, ruamel.yaml.nodes.MappingNode) and isinstance(b, ruamel.yaml.nodes.MappingNode):
            return _merge_mapping_nodes(a, b)
        # In all other cases, the later value wins
        return b

    merged = {}
    for key, val in nodes:
        key_id = key.value
        if key_id in merged:
            prev_key, prev_val = merged[key_id]
            merged[key_id] = (prev_key, _merge_values(prev_val, val))
        else:
            merged[key_id] = (key, val)

    return [(k, v) for k, v in merged.values()]

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def _merge_mapping_nodes(node_a, node_b):
        """Merge two MappingNode objects deeply. Return a new MappingNode."""
        # Ensure the nodes are MappingNodes
        if getattr(node_a, 'tag', None) != 'tag:yaml.org,2002:map' or getattr(node_b, 'tag', None) != 'tag:yaml.org,2002:map':
            return node_b
        # Build dictionary of first node's entries
        mapping = {}
        for k_node, v_node in node_a.value:
            mapping[k_node.value] = (k_node, v_node)
        # Merge second node's entries
        for k_node, v_node in node_b.value:
            key = k_node.value
            if key in mapping:
                existing_k_node, existing_v_node = mapping[key]
                # Recursively merge if both are MappingNodes
                if getattr(existing_v_node, 'tag', None) == 'tag:yaml.org,2002:map' and getattr(v_node, 'tag', None) == 'tag:yaml.org,2002:map':
                    merged_v = _merge_mapping_nodes(existing_v_node, v_node)
                else:
                    merged_v = v_node  # last wins
                mapping[key] = (existing_k_node, merged_v)
            else:
                mapping[key] = (k_node, v_node)
        # Preserve order of first appearance (from node_a then node_b)
        merged_value = [pair for pair in mapping.values()]
        return node_a.__class__(tag=node_a.tag, value=merged_value)

    def _merge_nodes(node_a, node_b):
        """Helper to merge two nodes, handling MappingNodes specially."""
