        from borgmatic.__main__ import cli  # type: ignore
    except Exception:
        # borgmatic might expose the click group under a different name
        try:
            from borgmatic import cli  # type: ignore
        except Exception:
            return ""

    try:
        from click_completion import BashCompleter  # type: ignore
    except Exception:
        # click-completion is not installed; cannot generate script
        return ""

