    # If the module directly provides a Click application in `cli`, we use it.
    # Otherwise, try to introspect for a click.Group object.
    cmd_group = None
    if hasattr(cli, "__click_module__"):
        cmd_group = cli
    elif hasattr(cli, "__click_main__"):
        cmd_group = cli.__click_main__
    elif hasattr(cli, "cli"):
        cmd_group = cli.cli
    else:
        # Attempt to find a click.Group in the module namespace
        for obj in vars(cli).values():
            try:
                if obj.__module__ and "click" in obj.__module__ and hasattr(obj, "commands"):
                    cmd_group = obj
                    break
            except Exception:
                continue

    if not cmd_group:
        return ""

    try:
        completer = BashCompleter(cmd_group)
        return completer.get_script()
    except Exception:
        # If script generation fails for any reason, fall back to empty string
        return ""

