def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two distinct symbols")
    if len(set(alphabet)) != base:
        raise ValueError("Alphabet contains duplicate symbols")
    digit_value = {ch: idx for idx, ch in enumerate(alphabet)}
    result = 0
    for ch in string:
        if ch not in digit_value:
            raise ValueError(f"Character '{ch}' not found in alphabet")
        result = result * base + digit_value[ch]
    return result

