              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    import shlex
    if platform == 'this':
        # Detect current platform: POSIX if not Windows
        posix = not sys.platform.startswith('win')
    else:
        # Treat truthy values as POSIX, falsy as Windows
        posix = bool(platform)
    return shlex.split(s, posix=posix)

