def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """

    tmp_path_str = str(tmp_path).rstrip("/")
    if filename:
        name = filename
    else:
        base = archive_path.split("/")[-1]
        for suffix in (".tar.gz", ".tgz", ".zip", ".tar.bz2"):
            if base.endswith(suffix):
                base = base[:-len(suffix)]
                break
        else:
            base = base.rsplit(".", 1)[0]
        name = base
    dest = f"{tmp_path_str}/{name}"
    subprocess.run(["mkdir", "-p", dest], check=True)

    if archive_path.endswith((".tar.gz", ".tgz", ".tar.bz2")):
        subprocess.run(["tar", "xf", archive_path, "-C", dest], check=True)
    elif archive_path.endswith(".zip"):
        subprocess.run(["unzip", "-q", archive_path, "-d", dest], check=True)
    else:
        raise ValueError(f"Unsupported archive type for {archive_path}")

    return f"file://{dest}"

