def make_find_paths(find_paths):
    """Convert path fragments in a `--find` list to glob patterns.

    Existing patterns that contain a colon (e.g. ``pp:root/somedir``) are
    returned unchanged.  Path fragments that do not contain a colon are
    wrapped as ``sh:**/*<fragment>*/**``.
    """
    transformed = []
    for part in find_paths:
        if ':' in part:
            transformed.append(part)
        else:
            transformed.append(f"sh:**/*{part}*/**")
    return transformed

