    """Call the given command(s)."""
    # Normalise input: commands can be a single string or list, same for args
    if isinstance(commands, str):
        commands = [commands]
    if isinstance(args, str):
        args = [args]
    # If args is a list but shorter (or longer) than commands, replicate it
    if isinstance(args, list) and len(args) != len(commands):
        if not args:
            args = [[] for _ in commands]
        else:
            args = [args[0]] * len(commands)
    outputs = []
