def gaussian(x):
    """Return Gaussian PDF values with mean 0.2 and sigma 0.1 evaluated at x."""
    mean, sigma = 0.2, 0.1
    x_arr = np.asarray(x)
    coeff = 1.0 / (sigma * np.sqrt(2 * np.pi))
    return coeff * np.exp(-((x_arr - mean) ** 2) / (2 * sigma ** 2))

