                    "exc_info": None,
                }
            )
            errors.append(record)

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    results = {}
    errors = []
    logger = logging.getLogger('load_configurations')
    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                content = f.read()
        except Exception as e:
            rec = logging.LogRecord(name=filename,
                                    level=logging.ERROR,
                                    pathname=filename,
                                    lineno=0,
                                    msg=str(e),
                                    args=(),
                                    exc_info=None)
            errors.append(rec)
            continue
        cfg = None
        # try YAML
        try:
            import yaml
            cfg = yaml.safe_load(content)
        except Exception:
            pass
        # try TOML
        if cfg is None:
            try:
                import toml
                cfg = toml.loads(content)
            except Exception:
                pass
        # try JSON
        if cfg is None:
            try:
                import json
                cfg = json.loads(content)
            except Exception:
                pass
        if cfg is None:
            rec = logging.LogRecord(name=filename,
                                    level=logging.ERROR,
                                    pathname=filename,
                                    lineno=0,
                                    msg="Unable to parse configuration",
                                    args=(),
                                    exc_info=None)
            errors.append(rec)
            continue
        # resolve environment variables
        if resolve_env:
            def resolve(val):
                if isinstance(val, str):
                    import os
                    return os.path.expandvars(val)
                elif isinstance(val, dict):
                    return {k: resolve(v) for k, v in val.items()}
                elif isinstance(val, list):
                    return [resolve(v) for v in val]
                else:
                    return val
            cfg = resolve(cfg)
        # apply overrides
        if overrides and isinstance(cfg, dict):
            cfg.update(overrides)
        results[filename] = cfg
    return results, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    error_records = []

    def _resolve_env_in_obj(obj):
        if isinstance(obj, dict):
            return {k: _resolve_env_in_obj(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_resolve_env_in_obj(v) for v in obj]
        if isinstance(obj, str):
            return os.path.expandvars(obj)
        return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                raw = f.read()
            ext = os.path.splitext(filename)[1].lower()
            if ext == '.json':
                import json
                parsed = json.loads(raw)
            elif ext in ('.yaml', '.yml'):
                import yaml
                parsed = yaml.safe_load(raw)
            elif ext == '.toml':
                import toml
                parsed = toml.loads(raw)
            else:
                parsed = raw
            if resolve_env:
                parsed = _resolve_env_in_obj(parsed)
            if overrides and isinstance(parsed, dict):
                parsed.update(overrides)
            configs[filename] = parsed
        except Exception as exc:
            logger = logging.getLogger()
            record = logger.makeRecord(
                name=logger.name,
                level=logging.ERROR,
                fn=filename,
                lno=0,
                msg="Failed to load configuration %s: %s" % (filename, exc),
                args=None,
                exc_info=exc
            )
            error_records.append(record)

    return configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    parsed_configs = {}
    error_records = []

    # Import modules lazily
    try:
        import yaml
    except ImportError:
        yaml = None
    try:
        import toml
    except ImportError:
        toml = None

    for filename in config_filenames:
        try:
            if not os.path.isfile(filename):
                raise FileNotFoundError(f"Configuration file not found: {filename}")

            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
            # Determine parser by file extension
            if filename.lower().endswith('.toml'):
                if toml is None:
                    raise ImportError("toml module not available")
                config = toml.loads(content) if content else {}
            elif filename.lower().endswith(('.yaml', '.yml')):
                if yaml is None:
                    raise ImportError("yaml module not available")
                config = yaml.safe_load(content) if content else {}
            else:
                # Unsupported format: treat as plain text
                raise ValueError(f"Unsupported configuration file format: {filename}")

            # Apply overrides if provided
            if overrides:
                config.update(overrides)

            # Resolve environment variables if required
            if resolve_env:
                for key, value in config.items():
                    if isinstance(value, str):
                        config[key] = os.path.expandvars(value)

            parsed_configs[filename] = config

        except Exception as exc:
            # Create a LogRecord to hold the error
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(exc),
                args=None,
                exc_info=None
            )
            error_records.append(record)

    return parsed_configs, error_records

